export function abrirModal(mensaje, onConfirmar) {
  const fondo = document.createElement('div');
  fondo.className = 'modal-fondo';
  fondo.innerHTML = `
    <div class="modal">
      <p>${mensaje}</p>
      <button id="aceptar">Aceptar</button>
      <button id="cancelar">Cancelar</button>
    </div>
  `;
  document.body.appendChild(fondo);

  function cerrar() {
    fondo.remove();
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') cerrar();
  });

  fondo.querySelector('#aceptar').addEventListener('click', () => {
    onConfirmar();
    cerrar();
  });
  fondo.querySelector('#cancelar').addEventListener('click', cerrar);
}

